import logging
from taf.ue.spark.client.util import remove_escape_sequences, remove_blank_lines


class ADB(object):
    def __init__(self, executor, serial_number=None):
        self._serial_number = serial_number or ""
        self._executor = executor

    @property
    def serial_number(self):
        return self._serial_number

    def execute_command(self, command, timeout=None):
        if not self._serial_number:
            command_prefix = "adb "
        else:
            command_prefix = "adb -s {} ".format(self._serial_number)
        command = command_prefix + command
        logging.debug("sending adb command：{}".format(command))
        response = self._executor.execute(command, timeout)
        logging.debug("original output from adb command：{}".format(response))
        valid_str = remove_blank_lines(remove_escape_sequences(response))
        logging.debug("valid output from adb command：{}".format(valid_str))
        return valid_str

    def start_app(self, app_package, activity, action=None, category=None, timeout=None):
        start_cmd = ("shell am start " + (
            "-a {} ".format(action) if action else "") + (
            "-c {} ".format(category) if category else "") + "-n {}/{}".format(app_package, activity))
        return self.execute_command(start_cmd, timeout)

    def stop_app(self, app_package, timeout=None):
        stop_cmd = "shell am force-stop {}".format(app_package)
        return self.execute_command(stop_cmd, timeout)

    def restart_ue_manager(self, timeout=None):
        stop_result = self.stop_app("com.ue.dmanager")
        logging.debug("stoping com.ue.dmanager with reponse {}".format(stop_result))

        start_result = self.start_app("com.ue.dmanager", "com.box.test.MainActivity",
                                      action="android.intent.action.MAIN",
                                      category="android.intent.category.LAUNCHER",
                                      timeout=timeout)
        logging.debug("starting com.ue.dmanager with reponse {}".format(start_result))

    def is_kirin_chip(self, timeout=None):
        """verify if the hardware is Kirin from Huawei"""

        response = self.execute_command("shell getprop ro.hardware", timeout)
        return "kirin" in response
